var __legadoJava = null;

function bindEnv(java) {
    __legadoJava = java;
}

function getLegadoJava() {
    if (__legadoJava) return __legadoJava;
    try {
        if (java) return java;
    } catch (e) {}
    throw 'Legado java helper unavailable';
}

function ytbAudioHeaders() {
    return {
        'User-Agent': 'okhttp/4.12.0',
        'Accept': '*/*',
        'Accept-Encoding': 'identity',
        'Referer': 'http://yuetingba.cn/'
    };
}

function ytbAesDecode(data) {
    var j = getLegadoJava();
    var key = j.base64DecodeToByteArray('le95G3hnFDJsBE+1/v9eYw==');
    var iv = j.base64DecodeToByteArray('IvswQFEUdKYf+d1wKpYLTg==');
    data = String(data || '').replace(/[\r\n\s]/g, '');
    return j.createSymmetricCrypto('AES/CBC/PKCS7Padding', key, iv).decryptStr(data);
}

function ytbKey(t, n) {
    var result = '';
    var i;
    for (i = 0; i < 20; i++) {
        result += String.fromCharCode(t.charCodeAt(i) + Number(n.charAt(i)));
    }
    for (i = 20; i < t.length; i++) {
        result += String.fromCharCode(t.charCodeAt(i) + Number(n.charAt(i - 20)));
    }
    return result;
}

function ytbIv(t, n) {
    var result = '';
    var i;
    for (i = 20; i > 4; i--) {
        result += String.fromCharCode(t.charCodeAt(i) + Number(n.charAt(i - 1)));
    }
    return result;
}

function ytbDecodeEfi(efi, tingId, creationTime) {
    var j = getLegadoJava();
    var idNoDash = String(tingId || '').replace(/-/g, '');
    var digits = String(creationTime || '').replace(/[-:T. ]/g, '');
    while (digits.length < 20) {
        digits += '0';
    }
    efi = String(efi || '').replace(/[\r\n\s]/g, '');
    return j.createSymmetricCrypto('AES/CBC/PKCS7Padding', ytbKey(idNoDash, digits), ytbIv(idNoDash, digits)).decryptStr(efi);
}

function ytbFixAssl(assl, es) {
    var result = {
        assl: String(assl || ''),
        sk: 'xMiP5W1DHBxC5PwQ5oj5QfRn0tsT5UBk'
    };
    es = Number(es || 0);
    if (es < 300) {
        es = result.assl.charCodeAt(0);
        if (result.assl.length - 32 > es) {
            result.sk = result.assl.substring(es, es + 32);
            result.assl = result.assl.substring(0, es) + result.assl.substr(es + 32);
        } else {
            result.sk = result.assl.substr(result.assl.length - 32);
            result.assl = result.assl.substr(0, result.assl.length - 32);
        }
    } else {
        result.assl = result.assl.replace(result.sk, '');
    }
    return result;
}

function ytbServerUrl(item) {
    if (!item) return '';
    if (item.Type == 'AAAA') {
        return item.Scheme + '://[' + item.Value + ']:' + item.Port;
    }
    return item.Scheme + '://' + item.Value + ':' + item.Port;
}

function ytbBookSuffix(bookId) {
    var parts = String(bookId || '').split('-');
    return parts.length > 4 ? parts[4] : '';
}

function ytbRatio(value) {
    var ratio = (Number(value)||0);
    if (isNaN(ratio) || ratio < 0) return 0;
    return ratio;
}

function ytbPickByRatio(list) {
    if (!list || list.length == 0) return null;
    var total = 0;
    var i;
    for (i = 0; i < list.length; i++) {
        total += ytbRatio(list[i].Ratio);
    }
    if (total <= 0) return list[0];
    var point = Math.floor(Math.random() * total) + 1;
    var sum = 0;
    for (i = 0; i < list.length; i++) {
        sum += ytbRatio(list[i].Ratio);
        if (point <= sum) return list[i];
    }
    return list[list.length - 1];
}

function ytbPickAudioServer(list, bookId, supportIpv6) {
    var audio = [];
    var i;
    for (i = 0; list && i < list.length; i++) {
        if (list[i].AsType == 1 && (supportIpv6 || list[i].Type == 'A')) {
            audio.push(list[i]);
        }
    }
    if (audio.length == 0) return '';

    var suffix = ytbBookSuffix(bookId);
    var matched = [];
    if (suffix) {
        for (i = 0; i < audio.length; i++) {
            if (audio[i].BookIds && String(audio[i].BookIds).indexOf(suffix) >= 0) {
                matched.push(audio[i]);
            }
        }
    }
    if (matched.length > 0) {
        audio = matched;
    } else if (audio.length > 1) {
        var ratioList = [];
        for (i = 0; i < audio.length; i++) {
            if (ytbRatio(audio[i].Ratio) > 0) ratioList.push(audio[i]);
        }
        if (ratioList.length > 0) audio = ratioList;

        var emptyBookIds = [];
        for (i = 0; i < audio.length; i++) {
            if (!audio[i].BookIds || String(audio[i].BookIds).replace(/\s/g, '') == '') {
                emptyBookIds.push(audio[i]);
            }
        }
        if (emptyBookIds.length > 0) audio = emptyBookIds;
    }

    return ytbServerUrl(ytbPickByRatio(audio));
}

function ytbFileName(url) {
    url = String(url || '');
    var s = url.lastIndexOf('/');
    if (s < 0) return '';
    var e = url.indexOf('?', s);
    if (e < 0) e = url.indexOf('#', s);
    if (e < 0) e = url.length;
    return url.substring(s + 1, e);
}

function ytbBuildPlayUrl(baseUrl, path, sk) {
    var raw = String(baseUrl || '') + String(path || '');
    var fileName = ytbFileName(raw);
    if (!fileName || !sk) return raw;
    var expire = Math.floor(new Date().getTime() / 1000) + 600;
    var token = getLegadoJava().md5Encode(fileName + '|' + expire + '|' + sk);
    return raw + '?token=' + token + '&expire=' + expire;
}

function ytbInitBookPage(html) {
    var j = getLegadoJava();
    html = String(html || '');
    try {
        var asslMatch = html.match(/var\s+assl\s*=\s*'([^']+)/);
        var bookIdMatch = html.match(/var\s+bookId\s*=\s*'([^']+)/);
        if (!asslMatch || !bookIdMatch) return html;
        var esMatch = html.match(/var\s+es\s*=\s*'([^']+)/);
        var supportIpv6 = /var\s+vs\s*=\s*true/.test(html);
        var fixed = ytbFixAssl(asslMatch[1], esMatch ? esMatch[1] : 0);
        var serverList = JSON.parse(ytbAesDecode(fixed.assl));
        var bookId = bookIdMatch[1];
        var audioBaseUrl = ytbPickAudioServer(serverList, bookId, supportIpv6);
        j.put('ytbBookId', bookId);
        j.put('ytbSk', fixed.sk);
        j.put('ytbServerList', JSON.stringify(serverList));
        j.put('ytbSupportIpv6', supportIpv6 ? '1' : '0');
        j.put('ytbAudioBaseUrl', audioBaseUrl);
        j.put('ytbCacheBookId', bookId);
        j.put('ytbAudioHeaders', JSON.stringify(ytbAudioHeaders()));
    } catch (e) {
        j.put('ytbInitError', String(e));
    }
    return html;
}

function ytbEnsureBookPageLoaded(expectedBookId) {
    var j = getLegadoJava();
    if (j.get('ytbServerList')) {
        var cacheBookId = j.get('ytbCacheBookId') || j.get('ytbBookId');
        if (!expectedBookId || cacheBookId == expectedBookId) return;
    }
