            var supportIpv6 = java.get('ytbSupportIpv6') == '1';
            baseUrl = ytbPickAudioServer(serverList, bookId, supportIpv6);
            if (baseUrl) java.put('ytbAudioBaseUrl', baseUrl);
        } catch (e) {}
    }
    if (!baseUrl) {
        result = '';
    } else {
        var path = ytbDecodeEfi(item.efi, item.id, item.creationTime);
        var url = ytbBuildPlayUrl(baseUrl, path, java.get('ytbSk'));
        result = url + ',{\"headers\":' + (java.get('ytbAudioHeaders') || JSON.stringify(ytbAudioHeaders())) + '}';
    }
}
